/* Local-only relationship preferences, isolated by owning demo workspace. */
const accountDirectory={retailer:[{id:'northstar',name:'Northstar Distribution',city:'Portland, OR',description:'Distribution · Primary sample supplier'},{id:'cascade',name:'Cascade Grove Supply',city:'Eugene, OR',description:'Distribution · Sample supplier'},{id:'shoreline',name:'Shoreline Brands',city:'Bend, OR',description:'Brand partner · Sample supplier'}],distributor:[{id:'evergreen',name:'Evergreen Retail',city:'Portland, OR',description:'South Main · Sample retail location'},{id:'harbor',name:'Harbor Cannabis Market',city:'Salem, OR',description:'Downtown · Sample retail location'},{id:'pine',name:'Pine & Peak Dispensary',city:'Bend, OR',description:'Westside · Sample retail location'}]};
const cadenceLabels={weekly:'Weekly',biweekly:'Bi-weekly · every 2 weeks',monthly:'Monthly'};
const accountStorageKey='par-account-preferences-v1';
let savedAccounts={};try{const parsed=JSON.parse(localStorage.getItem(accountStorageKey));if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))savedAccounts=parsed;}catch{}
const accountDrafts={};const selectedAccount={retailer:'northstar',distributor:'evergreen'};let accountQuery='';
function accountKey(owner,id){return owner+':'+id;}
function accountRecord(owner,id){const value=savedAccounts[accountKey(owner,id)];return {delivery:value&&Object.hasOwn(cadenceLabels,value.delivery)?value.delivery:'weekly',notes:typeof value?.notes==='string'?value.notes.slice(0,2000):'',updatedAt:typeof value?.updatedAt==='string'?value.updatedAt:null};}
function accountDraft(owner,id){const key=accountKey(owner,id);if(!accountDrafts[key])accountDrafts[key]={...accountRecord(owner,id),dirty:false};return accountDrafts[key];}
function renderAccounts(){const retailer=role==='retailer';$('account-page-title').textContent=retailer?'Vendors':'Retailers';$('directory-heading').textContent=retailer?'Your vendors':'Your retailers';$('account-page-description').textContent=retailer?'Manage vendor delivery preferences and keep notes for your retail team.':'Manage retailer delivery preferences and keep notes for your distribution team.';$('account-eyebrow').textContent=retailer?'RETAILER WORKSPACE · VENDOR ACCOUNTS':'DISTRIBUTOR WORKSPACE · RETAILER ACCOUNTS';$('account-search').placeholder=retailer?'Search vendors…':'Search retailers…';$('note-owner').textContent=retailer?'Internal to Evergreen Retail':'Internal to Northstar Distribution';renderAccountList();renderAccountDetail();}
function renderAccountList(){const filtered=accountDirectory[role].filter(a=>(a.name+' '+a.city).toLowerCase().includes(accountQuery.toLowerCase()));$('account-count').textContent=filtered.length+' account'+(filtered.length===1?'':'s');const list=$('account-list');list.replaceChildren();if(!filtered.length){const p=document.createElement('p');p.className='empty';p.textContent='No matching accounts. Try another name or city.';list.append(p);return;}filtered.forEach(account=>{const button=document.createElement('button');button.className='account-item'+(selectedAccount[role]===account.id?' selected':'');button.setAttribute('aria-pressed',String(selectedAccount[role]===account.id));const name=document.createElement('strong');name.textContent=account.name;const city=document.createElement('span');city.textContent=account.city;const cadence=document.createElement('small');const draft=accountDraft(role,account.id);const exists=savedAccounts[accountKey(role,account.id)];cadence.textContent=draft.dirty?'Unsaved changes':exists?cadenceLabels[draft.delivery]:'Delivery preference not set';button.append(name,city,cadence);button.onclick=()=>{selectedAccount[role]=account.id;renderAccountList();renderAccountDetail();};list.append(button);});}
function renderAccountDetail(){const account=accountDirectory[role].find(a=>a.id===selectedAccount[role]);$('account-empty').classList.toggle('hidden',!!account);$('account-fields').classList.toggle('hidden',!account);if(!account)return;const draft=accountDraft(role,account.id);$('account-name').textContent=account.name;$('account-meta').textContent=account.city+' · '+account.description;$('account-avatar').textContent=account.name.split(' ').map(w=>w[0]).slice(0,2).join('');$('account-delivery').value=draft.delivery;$('account-notes').value=draft.notes;renderAccountSaveStatus();}
function renderAccountSaveStatus(){const id=selectedAccount[role],draft=accountDraft(role,id);$('notes-length').textContent=draft.notes.length.toLocaleString()+' / 2,000';$('account-save-status').textContent=draft.dirty?'Unsaved changes — save when ready.':draft.updatedAt?'Saved in this browser · '+new Date(draft.updatedAt).toLocaleString():'Choose a preference and save it to this browser.';$('account-save-status').classList.toggle('unsaved',draft.dirty);}
function updateAccountDraft(){const draft=accountDraft(role,selectedAccount[role]);draft.delivery=$('account-delivery').value;draft.notes=$('account-notes').value.slice(0,2000);draft.dirty=true;renderAccountSaveStatus();renderAccountList();}
$('account-delivery').addEventListener('change',updateAccountDraft);$('account-notes').addEventListener('input',updateAccountDraft);
$('account-search').addEventListener('input',e=>{accountQuery=e.target.value;renderAccountList();});
$('save-account').onclick=()=>{const id=selectedAccount[role],draft=accountDraft(role,id),key=accountKey(role,id);if(!Object.hasOwn(cadenceLabels,draft.delivery))return;const saved={delivery:draft.delivery,notes:draft.notes,updatedAt:new Date().toISOString()};const next={...savedAccounts,[key]:saved};try{localStorage.setItem(accountStorageKey,JSON.stringify(next));savedAccounts=next;accountDrafts[key]={...saved,dirty:false};renderAccountSaveStatus();renderAccountList();toast('Account preferences saved in this browser.');}catch{$('account-save-status').textContent='Could not save. Browser storage is unavailable; keep this page open to retain your draft.';toast('Preferences were not saved. Browser storage is unavailable.');}};
$('role').addEventListener('change',()=>{accountQuery='';$('account-search').value='';renderAccounts();});
$('account-nav').addEventListener('click',renderAccounts);
window.addEventListener('beforeunload',e=>{if(Object.values(accountDrafts).some(d=>d.dirty)){e.preventDefault();e.returnValue='';}});
renderAccounts();
